import {requestAnalysis, startCompanion} from './companion.js';
import {parseTranscript, validateMessages, localAnalysis, contextFor} from './core.js';
const paths={chat:'M4 4h16v12H9l-5 5V4z',plus:'M12 5v14M5 12h14',book:'M4 4h6c1 0 2 1 2 2v15c0-2-2-3-4-3H4V4zm16 0h-6c-1 0-2 1-2 2v15c0-2 2-3 4-3h4V4z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3zM9 12l2 2 4-4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',upload:'M12 16V3m-4 4 4-4 4 4M4 16v5h16v-5',spark:'m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3z',arrow:'M5 12h14m-6-6 6 6-6 6',send:'m3 3 19 9-19 9 4-9-4-9zm4 9h15',copy:'M9 9h12v12H9zM15 5V3H3v12h2',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',down:'m6 9 6 6 6-6',more:'M5 12h.01M12 12h.01M19 12h.01',warn:'m12 3 10 18H2L12 3zm0 6v5m0 3h.01',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2',edit:'m16 3 5 5-13 13H3v-5L16 3z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',photo:'M3 4h18v16H3zm0 12 5-5 5 5 4-4 4 4M15 8h.01',lock:'M6 11h12v10H6zm2 0V7a4 4 0 1 1 8 0v4',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.chat}"/></svg>`;
const esc=(x='')=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sample=(id,title,name,subtitle,messages)=>({id,title,name,subtitle,note:'',messages:messages.map(([role,text])=>({role,text}))});
const samples=[sample('late','晚归的约定','小满','关于陪伴与期待',[
 ['partner','今天有点累，想早点回家。'],['me','辛苦啦，晚上一起吃饭？'],['partner','好呀，我等你。'],['me','临时有个会，可能要晚一点。'],['partner','大概多久呀？我还没吃。'],['me','还不确定，你先吃吧。'],['partner','算了，你忙吧。']
]),sample('tired','忙碌的一天','小满','先倾听，再给建议',[
 ['partner','今天的方案又被打回来了。'],['me','那你明天再改改？'],['partner','已经改三次了，真的好累。']
]),sample('weekend','周末的小计划','小满','把约定说清楚',[
 ['partner','周六我们去看那个展吧？'],['me','好，等我忙完订票。'],['partner','你上次也这么说，后来就忘了。']
])];
let state={chats:structuredClone(samples),active:'late',page:'chat',selected:6,tone:'warm',analysis:null,favorites:[],persist:false,live:false,endpoint:'',token:'',loading:false,mobileSheet:false};
try{const saved=JSON.parse(localStorage.getItem('xianwai-v1')||'null');if(saved?.persist){const chats=saved.chats.filter(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.title==='string'&&typeof c.note==='string'&&(c.messages.length===0||validateMessages(c.messages)));if(chats.length){state={...state,chats,active:chats[0].id,selected:null,favorites:Array.isArray(saved.favorites)?saved.favorites.filter(f=>typeof f.text==='string'&&typeof f.id==='string'):[],persist:true};}}}catch{}
const $=(s,root=document)=>root.querySelector(s);const current=()=>state.chats.find(c=>c.id===state.active)||state.chats[0];let generation=0,toastTimer,reviewRows=[];
function adoptCurrent(){const c=current();if(samples.some(sample=>sample.id===c.id)){c.id=crypto.randomUUID();state.active=c.id;c.title='我的聊天';c.name='对方';c.subtitle='已导入的聊天';}return c;}
function persist(){window.xianwaiPersistWorkspace?.(state);try{if(state.persist)localStorage.setItem('xianwai-v1',JSON.stringify({persist:true,chats:state.chats,favorites:state.favorites}));else localStorage.removeItem('xianwai-v1');}catch{toast('浏览器未允许保存，内容仍保留在当前页面。');}}
function toast(t){const node=$('#toast');node.textContent=t;node.classList.add('toast-show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('toast-show'),3200);}
function header(title,sub,eyebrow='A LITTLE CLOSER',button='import'){return `<div class="workspace-header"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${button?`<button class="outline-btn" data-action="${button}">${icon('upload')}导入聊天</button>`:''}</div>`;}
function render(){const c=current();$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brandmark">${icon('chat')}</span><div><strong>弦外</strong><small>BETWEEN THE LINES</small></div></div><button class="new-chat" data-action="new">${icon('plus')}开启一段对话</button><nav aria-label="主导航">${[['chat','chat','聊天工作台'],['favorites','heart','回复收藏'],['guide','book','使用指南']].map(([id,i,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}">${icon(i)}${label}${id==='favorites'?`<span class="count">${state.favorites.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-label">我的对话</div><div>${state.chats.map(chat=>`<button class="conversation ${chat.id===c.id&&state.page==='chat'?'active':''}" data-chat="${esc(chat.id)}"><span class="avatar ${chat.id==='late'?'peach':''}">${esc(chat.name.slice(0,1))}</span><span><strong>${esc(chat.title)}</strong><small>${chat.messages.length} 条消息 · ${chat.id==='late'?'示例':chat.id==='tired'||chat.id==='weekend'?'示例':'我的对话'}</small></span></button>`).join('')}</div><div class="sidebar-bottom"><div class="privacy-card">${icon('shield')}<p>${state.persist?'已开启本机保存':'聊天默认只在当前页面'}<br>每一次理解，都值得被保护。</p></div><button class="settings-btn" data-action="settings">${icon('settings')}设置与隐私</button></div></aside><main class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="打开导航">${icon('menu')}</button><span>沟通，有回声。</span><span>/</span><span>${state.page==='chat'?'聊天工作台':state.page==='favorites'?'回复收藏':'使用指南'}</span></div><div class="top-actions"><button class="mode-pill" data-action="settings"><span class="dot"></span>${state.live?'AI 服务已选择':'本地试用'}</button><button class="icon-btn" data-page="guide" aria-label="使用指南">${icon('book')}</button><span class="header-avatar">我</span></div></header>${state.page==='chat'?renderChat():state.page==='favorites'?renderFavorites():renderGuide()}</main></div>`;if(state.page==='chat'){renderAnalysis();const box=$('.chat-messages');if(box)box.scrollTop=box.scrollHeight;}bindLongPress();window.xianwaiCompanionRendered?.();}
function renderChat(){const c=current();return `${header('把话，听进心里。','导入截图，选中一句，找到你愿意说出口的回复。')}<div class="workbench"><section class="chat-panel" aria-label="聊天上下文"><div class="chat-head"><span class="avatar peach">${esc(c.name.slice(0,1))}</span><div><h2>${esc(c.name)}</h2><p>${esc(c.subtitle||'一起把话说清楚')} · ${c.messages.length} 条消息</p></div><button class="icon-btn" data-action="profile" aria-label="编辑对话信息">${icon('more')}</button></div><div class="context-bar">${icon('link')}已纳入导入的聊天上下文 <span>不会读取微信</span></div><div class="chat-messages"><div class="date-divider">${samples.some(s=>s.id===c.id)?'虚构示例 · 晚间对话':'本次导入 · 按原始顺序'}</div>${c.messages.length?c.messages.map((m,i)=>`<div class="msg ${m.role==='me'?'me':''} ${i===state.selected?'selected':''}" id="msg-${i}"><span class="avatar ${m.role==='partner'?'peach':''}">${m.role==='me'?'我':esc(c.name.slice(0,1))}</span><div class="msg-body"><div class="msg-name">${m.role==='me'?'我':esc(c.name)} <span style="opacity:.55">· ${i+1}</span></div><button class="bubble" data-message="${i}" aria-label="分析第 ${i+1} 条消息：${esc(m.text)}">${esc(m.text)}</button>${state.selected===i?`<div class="selected-hint">${icon('spark')}已选中 · 查看这一句的分析</div>`:''}</div></div>`).join(''):`<div class="empty-state"><h2>从一段真实的对话开始</h2><p>粘贴聊天，或在下方逐条补充。<br>请先移除不必要的姓名、地址和联系方式。</p><button class="primary-btn" data-action="import">${icon('upload')}导入聊天</button></div>`}</div><div class="chat-tip">${icon('spark')}长按一条消息，看见话背后的可能含义 <span class="keyboard-hint">· 也可点击或按 Enter</span></div><form class="composer" id="composer"><select name="role" aria-label="添加消息的发送者"><option value="partner">对方</option><option value="me">我</option></select><textarea name="message" aria-label="补充聊天消息" placeholder="补充一句聊天，让语境更完整…" maxlength="2000" rows="1"></textarea><button type="submit" aria-label="添加到上下文">${icon('plus')}</button></form></section><div class="analysis-scrim ${state.mobileSheet?'open':''}" data-action="close-analysis"></div><section class="analysis-panel ${state.mobileSheet?'open':''}" aria-label="消息分析" id="analysis"></section></div>`;}
function renderAnalysis(){const c=current(),node=$('#analysis');if(!node)return;const a=state.analysis,m=c.messages[state.selected];node.innerHTML=`<div class="analysis-header"><div class="analysis-title">${icon('spark')}<h2>这一句，怎么接</h2></div><small>${state.loading?'正在理解上下文':a?.mode==='ai'?'AI 语境分析':!a&&state.live?'AI 已就绪':'本地规则试用'}</small><button class="icon-btn mobile-close" data-action="close-analysis" aria-label="关闭分析">${icon('close')}</button></div>${state.loading?`<div class="analysis-empty"><div class="spinner"></div><h3>把前后文放在一起听</h3><p>正在分析目标消息及之前的 ${state.selected+1} 条消息…</p></div>`:!a||!m?`<div class="analysis-empty">${icon('chat')}<h3>${c.messages.length?'每句话，都有它的语境':'先放进一段聊天'}</h3><p>选择左侧的一条消息，<br>看看可能的感受、需求和回复方式。</p>${state.analysisError?`<p class="error">${esc(state.analysisError)}</p><button class="outline-btn" data-action="retry">重新分析</button>`:''}</div>`:`<div class="analysis-scroll"><div class="quote"><span>回应 ${m.role==='me'?'自己':esc(c.name)} · 消息 ${state.selected+1}</span>“${esc(m.text)}”</div><div class="insight-card"><div class="mini-label">${icon('spark')}${a.mode==='ai'?'结合语境的建议':'本地试用 · 基于关键词的沟通提示'}</div><h3>${esc(a.title)}</h3><p><b>可能的感受</b> · ${esc(a.feeling)}</p><p><b>值得确认的需求</b> · ${esc(a.need)}</p></div><div class="section-heading"><h3>${icon('heart')}${m.role==='me'?'这句话可以怎样调整':'对方可能想表达什么'}</h3><small>推测，需要和本人确认</small></div>${a.hypotheses.map(h=>`<div class="hypothesis">${esc(h.text)}${citations(h.evidence)}</div>`).join('')}<details class="facts"><summary>查看原话依据 · ${a.contextCount} 条语境消息</summary>${a.facts.map(f=>`<p class="fact">${esc(f.text)}${citations(f.evidence)}</p>`).join('')}<p class="fact">回复只参考目标消息及之前的内容，后续 ${c.messages.length-state.selected-1} 条未用于回应该句。${c.note?' 已纳入你补充的关系背景。':''}</p></details><div class="section-heading"><h3>${icon('chat')}可以这样回复</h3><div class="tone-switch" aria-label="回复语气">${[['warm','温柔一点'],['honest','坦诚一点'],['brief','简短一点']].map(([id,label])=>`<button class="${state.tone===id?'active':''}" data-tone="${id}" aria-pressed="${state.tone===id}">${label}</button>`).join('')}</div></div>${a.replies.map((r,i)=>`<article class="reply-card ${i===0?'featured':''}"><div class="reply-top"><span>${i===0?icon('spark'):''}${esc(r.label)}</span><div class="reply-actions"><button data-edit="${i}" aria-label="编辑第 ${i+1} 个回复">${icon('edit')}编辑</button><button data-save="${i}" class="${state.favorites.some(f=>f.text===r.text)?'saved':''}" aria-label="收藏第 ${i+1} 个回复">${icon('heart')}</button><button data-copy="${i}">${icon('copy')}复制</button></div></div><p>${esc(r.text)}</p><div class="reason">${esc(r.reason)}</div></article>`).join('')}<div class="avoid">${icon('warn')}<div>${esc(a.avoid)}</div></div><div class="analysis-foot">${a.mode==='local'?'本地试用不调用大模型，结果是规则提示。<br>':''}这些是可能的解释。真正的答案，来自你们的沟通。</div></div>`}`;}
function citations(ids){return(ids||[]).map(id=>`<button class="citation" data-ref="${id-1}">原话 ${id}</button>`).join('');}
function renderFavorites(){return `${header('留住，好好说话的时刻。','收藏的回复只属于你的工作台。','WORDS TO KEEP',null)}<div class="page-content">${state.favorites.length?state.favorites.map(f=>`<article class="collection-item"><small>${esc(f.name)} · ${esc(f.label)}</small><p>${esc(f.text)}</p><footer><small>${esc(f.source||'自定义回复')}</small><button class="outline-btn" data-fav-copy="${esc(f.id)}">${icon('copy')}复制</button><button class="icon-btn" data-fav-remove="${esc(f.id)}" aria-label="移除收藏">${icon('trash')}</button></footer></article>`).join(''):`<div class="empty-state"><h2>一句合适的话，值得留下</h2><p>在回复建议旁点击爱心，即可收藏。<br>${state.persist?'本机保存已开启。':'默认关闭页面后清除，可在设置中开启本机保存。'}</p><button class="primary-btn" data-page="chat">回到聊天工作台 ${icon('arrow')}</button></div>`}</div>`;}
function renderGuide(){return `${header('靠近，从听懂开始。','用工具留意语境，用真实的沟通确认彼此。','A SMALL GUIDE',null)}<div class="page-content"><div class="reading-grid">${[['01','把语境放在一起','先粘贴带发送者的聊天文本，或导入 TXT / JSON。最多 300 条、80,000 字，不会静默截断。导入前可逐条核对说话人。','连接 Mac 后，网页可从相册批量选择微信截图，在 Mac 使用 Apple Vision 识别。识别后先核对顺序、发送者和文字，再分析。'],['02','选中你想回应的那一句','在本工作台里长按、点击消息，或用键盘选中后按 Enter。分析使用目标消息及之前的全部已导入内容，可补充关系背景。','iOS 的应用隔离限制了跨 App 读取。这个版本不会读取微信后台，也不能在微信原有的长按菜单中添加功能。'],['03','先看依据，再选怎么说','分析把原话和可能的解释分开。点击“原话”可定位消息。没有单句消息能证明一个人的真实心思。','用温柔、坦诚、简短三种语气起草回复。根据自己的真实情况编辑后复制，再回微信发送；不要承诺做不到的事。'],['04','让私密内容由你决定','未配对时默认只在当前页面保留内容。配对时可选择保存到当前设备与 Mac，下次连接可以恢复，也可主动清除。','手机扫码连接 Mac 可复用已登录的 Codex，无需密钥。截图通过 Cloudflare 连接到 Mac；选择分析时相关文字发送给 OpenAI。模型结果可能不准确。']].map(([n,t,p,q])=>`<article class="reading-card"><div class="step">${n}</div><h2>${t}</h2><p>${p}</p><p>${q}</p></article>`).join('')}</div></div>`;}
async function analyze(index,open=true){const c=current();if(!c.messages[index])return;state.selected=index;state.mobileSheet=open;state.analysisError='';const seq=++generation;state.loading=state.live;state.analysis=null;render();if(!state.live){state.analysis=localAnalysis(c.messages,index,state.tone);renderAnalysis();return;}try{const base=state.endpoint.replace(/\/$/,'');if(base){const u=new URL(base);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw new Error('AI 服务请使用 HTTPS 地址。');}const a=await requestAnalysis({endpoint:base,token:state.token,input:{messages:c.messages,targetIndex:index,tone:state.tone,note:c.note||''}});if(seq!==generation)return;if(!a||a.mode!=='ai'||!Array.isArray(a.replies))throw new Error('服务返回的分析格式不正确。');state.analysis=a;}catch(err){if(seq!==generation)return;state.analysisError=err.name==='TimeoutError'?'分析超时，请稍后重试。':err.message;toast(state.analysisError);}finally{if(seq===generation){state.loading=false;renderAnalysis();window.xianwaiCompanionRendered?.();}}}
function selectChat(id){generation++;state.active=id;state.page='chat';state.selected=null;state.analysis=null;state.loading=false;state.mobileSheet=false;render();}
function modal(title,intro,body,footer=''){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭窗口">${icon('close')}</button></div><p class="intro">${intro}</p>${body}<div class="error" id="modal-error" role="alert"></div><div class="modal-footer">${footer}</div></section></div>`;const focusable=root.querySelectorAll('button,input,textarea,select');setTimeout(()=>focusable[1]?.focus(),20);}
function closeModal(){$('#modal-root').innerHTML='';}
function modalError(t){$('#modal-error').textContent=t;}
function openImport(raw=''){modal('把聊天带进来','粘贴一段聊天，再核对说话人。仅替换当前对话，最多 300 条。',`<label for="transcript">聊天内容</label><textarea id="transcript" placeholder="我：今晚一起吃饭？&#10;对方：好呀，我等你。&#10;我：临时有个会，可能晚一点。">${esc(raw)}</textarea><div class="import-tools"><button class="outline-btn" data-action="choose-file">${icon('upload')}TXT / JSON 文件</button><button class="outline-btn" data-action="screenshot">${icon('photo')}截图识别</button></div><input id="file-input" type="file" accept=".txt,.json,text/plain,application/json" hidden><div class="notice">没有标记发送者的行会暂记为“对方”并高亮，请在下一步确认。请只导入你有权使用的内容，先移除不必要的私人信息。</div>`,`<button class="outline-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="parse">下一步 · 核对消息 ${icon('arrow')}</button>`);}
function showReview(){modal('再确认一遍，才好理解','按时间顺序排列。黄色行的发送者是暂定的，请核对。导入会替换当前对话的消息。',`${current().messages.length?`<label class="checkbox-row"><input id="append-import" type="checkbox" ${!samples.some(x=>x.id===current().id)?'checked':''}>追加到当前对话（已有 ${current().messages.length} 条）</label>`:''}<div id="review-rows">${reviewRows.map((r,i)=>`<div class="review-row ${r.uncertain?'uncertain':''}" data-row="${i}"><select aria-label="第 ${i+1} 条发送者"><option value="partner" ${r.role==='partner'?'selected':''}>对方</option><option value="me" ${r.role==='me'?'selected':''}>我</option></select><textarea aria-label="第 ${i+1} 条文字" maxlength="2000">${esc(r.text)}</textarea><button class="icon-btn" data-remove-row="${i}" aria-label="删除第 ${i+1} 条">${icon('trash')}</button></div>`).join('')}</div>`,`<button class="outline-btn" data-action="back-import">返回粘贴</button><button class="primary-btn" data-action="confirm-import">确认导入 ${reviewRows.length} 条 ${icon('check')}</button>`);}
function collectRows(){return [...document.querySelectorAll('.review-row')].map(r=>({role:$('select',r).value,text:$('textarea',r).value}));}
function settings(){const paired=window.xianwaiIsConnected?.();modal('让理解，按你的方式发生',paired?'已通过 Mac 连接 Codex，不需要模型密钥。':'扫码连接 Mac，即可识别截图并使用真实 AI。',`<label class="checkbox-row"><input type="checkbox" id="persist" ${state.persist?'checked':''}>保存聊天与收藏${paired?'到当前设备和 Mac':''}（未加密）</label><label class="checkbox-row"><input type="checkbox" id="live" ${state.live?'checked':''}>使用在线 AI 分析（相关文字和背景会发送给模型服务）</label><div class="notice">${paired?'截图通过加密连接送到你的 Mac 进行识别；分析文字通过 Codex 发送给 OpenAI，并使用你的当前账户额度。关闭 Mac 应用后，需重新扫码连接。':'在 Mac 上打开弦外应用，扫描二维码即可配对。不连接时仍可使用明确标注的本地规则提示。'}</div><details><summary style="font-size:11px;color:#839373;margin-top:18px;cursor:pointer">高级连接设置</summary><label for="endpoint">后端地址</label><input id="endpoint" type="url" value="${esc(state.endpoint)}" placeholder="留空使用当前站点"><label for="token">访问令牌</label><input id="token" type="password" value="${esc(state.token)}" autocomplete="off" placeholder="配对时自动填写"></details><button class="danger-btn" data-action="clear">清除当前设备与 Mac 备份中的聊天和收藏…</button>`,`<button class="outline-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="save-settings">保存设置 ${icon('check')}</button>`);}
function editProfile(){const c=current();modal('给这段对话一点背景','只填写有助于理解的事实。背景也会参与在线 AI 分析。',`<label for="chat-title">对话标题</label><input id="chat-title" maxlength="30" value="${esc(c.title)}"><label for="partner-name">对方的称呼</label><input id="partner-name" maxlength="20" value="${esc(c.name)}"><label for="context-note">关系与背景 · 可选</label><textarea id="context-note" maxlength="2000" placeholder="例如：交往两年；今晚约好一起吃饭；最近双方都在加班。">${esc(c.note)}</textarea>`,`<button class="outline-btn" data-action="export">${icon('download')}导出聊天</button><button class="primary-btn" data-action="save-profile">保存背景</button>`);}
async function copyText(t){if(window.webkit?.messageHandlers?.xianwai){window.webkit.messageHandlers.xianwai.postMessage({action:'copy',text:t});toast('已复制，回微信前再确认一下语气。');return;}try{await navigator.clipboard.writeText(t);toast('已复制，回微信前再确认一下语气。');}catch{modal('复制这句话','浏览器未允许自动复制，可选择下面的文字手动复制。',`<textarea id="manual-copy">${esc(t)}</textarea>`,`<button class="primary-btn" data-action="close-modal">完成</button>`);$('#manual-copy').select();}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-action]');if(!b)return;const action=b.dataset.action;if(b.dataset.page){state.page=b.dataset.page;state.mobileSheet=false;render();return;}if(b.dataset.chat){selectChat(b.dataset.chat);return;}if(b.dataset.message!==undefined){analyze(Number(b.dataset.message));return;}if(b.dataset.ref!==undefined){if(matchMedia('(max-width:950px)').matches){state.mobileSheet=false;$('.analysis-panel')?.classList.remove('open');$('.analysis-scrim')?.classList.remove('open');}const msg=$('#msg-'+b.dataset.ref);msg?.scrollIntoView({behavior:'smooth',block:'center'});msg?.animate([{opacity:.4},{opacity:1}],{duration:600});return;}if(b.dataset.tone){state.tone=b.dataset.tone;if(state.selected!==null)analyze(state.selected,state.mobileSheet);return;}if(b.dataset.copy!==undefined){copyText(state.analysis.replies[Number(b.dataset.copy)].text);return;}if(b.dataset.edit!==undefined){const r=state.analysis.replies[Number(b.dataset.edit)];modal('改成你自己的话','先确认回复符合真实情况，再复制发送。',`<textarea id="edit-reply">${esc(r.text)}</textarea>`,`<button class="outline-btn" data-action="close-modal">取消</button><button class="primary-btn" data-action="copy-edited">${icon('copy')}复制编辑后的回复</button>`);return;}if(b.dataset.save!==undefined){const r=state.analysis.replies[Number(b.dataset.save)],existing=state.favorites.find(f=>f.text===r.text);if(existing)state.favorites=state.favorites.filter(f=>f.id!==existing.id);else state.favorites.unshift({id:crypto.randomUUID(),text:r.text,label:r.label,name:current().name,source:current().title});persist();renderAnalysis();const count=$('.nav-item .count');if(count)count.textContent=state.favorites.length;toast(existing?'已移除收藏':'已收藏这句话');return;}if(b.dataset.favCopy){copyText(state.favorites.find(f=>f.id===b.dataset.favCopy).text);return;}if(b.dataset.favRemove){state.favorites=state.favorites.filter(f=>f.id!==b.dataset.favRemove);persist();render();return;}if(b.dataset.removeRow!==undefined){reviewRows=collectRows();reviewRows.splice(Number(b.dataset.removeRow),1);showReview();return;}
switch(action){case'menu':$('#sidebar').classList.toggle('open');break;case'import':openImport();break;case'close-modal':closeModal();break;case'settings':settings();break;case'profile':editProfile();break;case'close-analysis':state.mobileSheet=false;$('.analysis-panel')?.classList.remove('open');$('.analysis-scrim')?.classList.remove('open');break;case'new':{if(state.chats.length>=15){toast('最多保留 15 段对话，请先导出并清理。');break;}const c={id:crypto.randomUUID(),title:'新的对话',name:'对方',subtitle:'给彼此多一点理解',note:'',messages:[]};state.chats.unshift(c);persist();selectChat(c.id);openImport();break;}case'choose-file':$('#file-input').click();break;case'parse':try{reviewRows=parseTranscript($('#transcript').value);showReview();}catch(err){modalError(err.message);}break;case'back-import':{reviewRows=collectRows();openImport(reviewRows.map(r=>(r.role==='me'?'我':'对方')+'：'+r.text).join('\n'));break;}case'confirm-import':try{const messages=validateMessages([...(document.querySelector('#append-import')?.checked?current().messages:[]),...collectRows()]);adoptCurrent().messages=messages;state.selected=null;state.analysis=null;generation++;persist();closeModal();render();toast(`已导入 ${messages.length} 条消息，长按一句开始理解。`);}catch(err){modalError(err.message);}break;case'screenshot':if(window.xianwaiImportScreenshots){window.xianwaiImportScreenshots();}else if(window.webkit?.messageHandlers?.xianwai){toast('正在打开相册，图片将在本机识别。');window.webkit.messageHandlers.xianwai.postMessage({action:'pickScreenshot'});}else{modal('在 iPhone 上识别截图','网页原型暂不识别图片。iPhone 源码版内置 Apple Vision 本机文字识别。',`<div class="notice">在 iPhone App 的“导入聊天 → 截图识别”中，从相册选择截图。识别后的文字先进入核对界面，不会自动上传。网页可以粘贴已有文字，或导入 TXT / JSON。</div>`,`<button class="primary-btn" data-action="import">返回文字导入</button>`);}break;case'save-settings':{const endpoint=$('#endpoint').value.trim().replace(/\/$/,'');if(endpoint){try{const u=new URL(endpoint);if(u.username||u.password||u.search||u.hash||u.pathname!=='/'||(u.protocol!=='https:'&&!(u.protocol==='http:'&&['127.0.0.1','localhost'].includes(u.hostname))))throw new Error();}catch{modalError('请输入不带路径和参数的 HTTPS 后端地址，本机可用 http://localhost:4388。');break;}}state.persist=$('#persist').checked;state.live=$('#live').checked;state.endpoint=endpoint;state.token=$('#token').value.trim();generation++;state.loading=false;state.analysis=null;persist();closeModal();if(state.selected!==null)analyze(state.selected,false);else render();toast(state.live?'已开启在线 AI，聊天将发送至你配置的服务。':'已切换为本地规则试用');break;}case'save-profile':{const c=current();c.title=$('#chat-title').value.trim()||'新的对话';c.name=$('#partner-name').value.trim()||'对方';c.note=$('#context-note').value.trim();persist();closeModal();if(state.selected!==null)analyze(state.selected,false);else render();break;}case'copy-edited':copyText($('#edit-reply').value);break;case'retry':if(state.selected!==null)analyze(state.selected);break;case'export':{const c=current(),data=JSON.stringify(c.messages,null,2);if(window.webkit?.messageHandlers?.xianwai){window.webkit.messageHandlers.xianwai.postMessage({action:'export',text:data});break;}const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='弦外-聊天.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('已导出聊天 JSON');break;}case'clear':modal('清除这台设备的内容','这会删除当前工作台的聊天和收藏、已连接 Mac 的备份，并关闭保存。请先导出需要保留的聊天。',`<div class="notice">无法撤销此操作。清除后显示的三个对话是虚构示例，不包含你的内容。</div>`,`<button class="outline-btn" data-action="settings">返回设置</button><button class="primary-btn" data-action="confirm-clear">确认清除</button>`);break;case'confirm-clear':window.xianwaiDeleteBackup?.();generation++;state={...state,chats:structuredClone(samples),favorites:[],persist:false,active:'late',selected:null,analysis:null,loading:false,page:'chat',mobileSheet:false,live:false,endpoint:'',token:''};persist();closeModal();render();toast('已清除本机聊天与收藏。');break;}});
document.addEventListener('submit',e=>{if(e.target.id!=='composer')return;e.preventDefault();const f=e.target,text=f.elements.message.value.trim();if(!text)return;try{const messages=validateMessages([...current().messages,{role:f.elements.role.value,text}]);generation++;state.loading=false;adoptCurrent().messages=messages;state.analysis=null;state.selected=null;persist();render();toast('已加入上下文，点击消息即可分析。');}catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{if(e.target.id!=='file-input')return;const f=e.target.files[0];if(!f)return;if(f.size>500000){modalError('文件超过 500 KB，请拆分后导入。');return;}try{$('#transcript').value=await f.text();toast('已读取文件，下一步核对消息。');}catch{modalError('无法读取这个文件，请尝试粘贴文字。');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();state.mobileSheet=false;$('.analysis-panel')?.classList.remove('open');$('.analysis-scrim')?.classList.remove('open');$('#sidebar')?.classList.remove('open');}if(e.key==='Tab'&&$('#modal-root .modal')){const items=[...$('#modal-root').querySelectorAll('button,input,textarea,select')].filter(x=>!x.hidden&&!x.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}}});
function bindLongPress(){document.querySelectorAll('[data-message]').forEach(b=>{let timer,x,y,fired=false;b.addEventListener('pointerdown',e=>{if(e.button!==0)return;fired=false;x=e.clientX;y=e.clientY;timer=setTimeout(()=>{fired=true;navigator.vibrate?.(15);analyze(Number(b.dataset.message));},450);});b.addEventListener('pointermove',e=>{if(Math.abs(e.clientX-x)>8||Math.abs(e.clientY-y)>8)clearTimeout(timer);});for(const event of ['pointerup','pointercancel','pointerleave'])b.addEventListener(event,()=>clearTimeout(timer));b.addEventListener('click',e=>{if(fired){e.preventDefault();e.stopPropagation();} });b.addEventListener('contextmenu',e=>{e.preventDefault();clearTimeout(timer);analyze(Number(b.dataset.message));});});}
window.xianwaiReceiveOCR=(rows)=>{try{reviewRows=validateMessages(rows).map(r=>({...r,uncertain:true}));showReview();toast('识别完成，请核对发送者、文字和顺序。');}catch(err){toast(err.message);}};
window.xianwaiError=message=>toast(message);
state.analysis=state.selected!==null?localAnalysis(current().messages,state.selected,state.tone):null;render();

startCompanion({getState:()=>state,modal,closeModal,toast,render,showReview,setReviewRows:rows=>{reviewRows=rows;},escape:esc,persist,openImport,stopAnalysis:()=>{generation++;state.loading=false;state.analysis=null;state.analysisError='已取消这次分析，可以重新选择消息。';renderAnalysis();}});
